  layerCanvas.blendMode = "layer";
  canvas.addChild( layerCanvas );

  // Create a new layer, binding alpha and blendMode with original layer
  var layer = Akari.Display.Layer(
  {
    source : canvas,
    inPoint : original.inPoint,
    outPoint : original.outPoint
  });

