function Comp_heart()
{
  var dimensionCubic = Interpolation.dimension( Interpolation.cubic.easeInOut );

  return Composition(
  {
    layers :
    [
      Layer(
      {
        source : Anchor({ source : shape,x:200,y:800 }),
        properties :
        {
          // Place a function on X-axis to make it move according to time
          scaleX: function( time ) 
            {
               var size=(time%468.75)/468.75; 
               If(size<0.75)
                size=0.75;
                Return size;
             },
        scaleY: function( time )   {
               var size=(time%468.75)/468.75; 
               If(size<0.75)
                size=0.75;
                Return size;
             },          
          y : 0,
          x : 0
        }
      })
    ]
  });
}


